import React from 'react';

interface RelativeTextCenterProps {
  /** The element to render (e.g., 'div', 'section', etc.) */
  as?: keyof JSX.IntrinsicElements | React.ComponentType<any>;
  /** Additional className to apply */
  className?: string;
  /** All other props are spread to the underlying element */
}

export const RelativeTextCenter: React.FC<RelativeTextCenterProps> = ({
  as = 'div',
  className,
  ...props
}) => {
  const baseClasses = 'relative text-center';
  const allClasses = [baseClasses, className].filter(Boolean).join(' ');

  return React.createElement(as, {
    className: allClasses,
    ...props
  });
});
