import React from 'react';
import { render, screen } from '@testing-library/react';
import '@testing-library/jest-dom';
import { RelativeTextCenter } from './RelativeTextCenter';

describe('RelativeTextCenter', () => {
  test('renders base classes', () => {
    render(<RelativeTextCenter />);
    const element = screen.getByText(/^$/i);
    expect(element).toHaveClass('relative');
    expect(element).toHaveClass('text-center');
  });

  test('appends additional className', () => {
    const additional = 'p-4 bg-blue-500';
    render(<RelativeTextCenter className={additional} />);
    const element = screen.getByText(/^$/i);
    expect(element).toHaveClass('relative');
    expect(element).toHaveClass('text-center');
    expect(element).toHaveClass('p-4');
    expect(element).toHaveClass('bg-blue-500');
  });

  test('allows changing the element via as prop', () => {
    const asElement = 'section';
    render(<RelativeTextCenter as={asElement} />);
    const element = screen.getByText(/^$/i);
    expect(element.tagName.toLowerCase()).toBe(asElement);
  });

  test('spreads other props to the underlying element', () => {
    const onClick = jest.fn();
    render(<RelativeTextCenter onClick={onClick} />);
    const element = screen.getByText(/^$/i);
    element.click();
    expect(onClick).toHaveBeenCalledTimes(1);
  });
});
